const raw = $json;
const d = (raw.body && raw.body.file_b64 !== undefined) ? raw.body : raw;
return [{ json: {
  type: (d.type === 'video') ? 'video' : 'image',
  file_b64: d.file_b64 || '',
  mime_type: d.mime_type || 'image/jpeg',
  caption: d.caption || '',
  preview_b64: d.preview_b64 || null,
  preview_mime_type: d.preview_mime_type || null
} }];

const res = $input.first().json;
const raw = (res.content && res.content[0] && res.content[0].text) ? res.content[0].text : '{}';
let txt = raw.trim();
if (txt.startsWith('```')) { txt = txt.substring(txt.indexOf('\n') + 1); if (txt.endsWith('```')) txt = txt.slice(0, -3); txt = txt.trim(); }
let parsed = {};
try { parsed = JSON.parse(txt); } catch (e) { parsed = {}; }

const allowed = ['tv_shows','streaming','gadgets','tools','games','movies','ai','anime','esports','other'];
const category = allowed.includes(parsed.category) ? parsed.category : 'other';
const summary = (parsed.summary || '').toString();
const tags = Array.isArray(parsed.tags) ? parsed.tags.slice(0, 5).map(t => String(t)) : [];

const prep = $('Prepare Data').first().json;
return [{ json: {
  category, summary, tags,
  caption: prep.caption,
  preview_b64: prep.file_b64,
  preview_mime_type: prep.mime_type
} }];

